import {frame,scale,axes,legend,esc} from '../shared.js';
import {seriesColors} from '../figure-themes.js';
export function render({data,params:p}){const f=frame(p),x=scale(data.map(d=>d.x),f.left,f.right,p.xMin,p.xMax),y=scale(data.map(d=>d.y),f.bottom,f.top,p.yMin,p.yMax),groups=[...new Set(data.map(d=>d.group))],colors=seriesColors(p,[p.color,p.color2]);let s=f.start+axes(f,x,y);groups.forEach((g,i)=>{const rows=data.filter(d=>d.group===g).sort((a,b)=>a.x-b.x),c=colors[i%colors.length];s+=`<polyline points="${rows.map(d=>`${x(d.x)},${y(d.y)}`).join(' ')}" fill="none" stroke="${esc(c)}" stroke-width="${p.lineWidth}"/>`;for(const d of rows){if(p.marker==='圆形')s+=`<circle cx="${x(d.x)}" cy="${y(d.y)}" r="4" fill="${esc(c)}"/>`;if(p.marker==='方形')s+=`<rect x="${x(d.x)-4}" y="${y(d.y)-4}" width="8" height="8" fill="${esc(c)}"/>`;}});return s+legend(f,p,groups,colors)+f.end;}
